def live_compliance_enrollment_errors(school, payload: dict[str, Any]) -> list[str]:
    """
    Return user-facing error strings if validation fails; empty if OK or feature off.
    """
    if school is None:
        return []
    settings = getattr(school, "settings", None) or {}
    if not isinstance(settings, dict):
        return []
    if not settings.get("compliance_live_validation"):
        return []
    errs: list[str] = []
    if not (payload.get("enrollment_date") or payload.get("start_date")):
        errs.append(
            "enrollment_date (or start_date) is required when live compliance validation is enabled for this school."
        )
    if payload.get("student_id") in (None, "") and payload.get("student_user_id") in (
        None,
        "",
    ):
        errs.append("student reference is required for enrollment records.")
    return errs

def live_compliance_attendance_errors(school, payload: dict[str, Any]) -> list[str]:
    if school is None:
        return []
    settings = getattr(school, "settings", None) or {}
    if not isinstance(settings, dict) or not settings.get("compliance_live_validation"):
        return []
    errs: list[str] = []
    if not payload.get("session_date") and not payload.get("date"):
        errs.append(
            "session date is required when live compliance validation is enabled."
        )
    if not payload.get("status") and not payload.get("attendance_code"):
        errs.append("attendance status or code is required.")
    return errs

def _normalize_course_code(value: Any) -> str:
    if value is None:
        return ""
    return str(value).strip().upper()

def _normalize_code_list(values: Iterable[Any] | None) -> list[str]:
    if not values:
        return []
    out: list[str] = []
    seen: set[str] = set()
    for raw in values:
        code = _normalize_course_code(raw)
        if not code or code in seen:
            continue
        seen.add(code)
        out.append(code)
    return out

def _normalize_code_map(value: Any) -> dict[str, list[str]]:
    if not isinstance(value, dict):
        return {}
    out: dict[str, list[str]] = {}
    for raw_key, raw_values in value.items():
        key = _normalize_course_code(raw_key)
        if not key:
            continue
        if isinstance(raw_values, (list, tuple, set)):
            out[key] = _normalize_code_list(raw_values)
        elif raw_values is None:
            out[key] = []
        else:
            out[key] = _normalize_code_list([raw_values])
    return out

def _to_decimal(value: Any, default: Decimal) -> Decimal:
    try:
        if value is None or value == "":
            return default
        return Decimal(str(value))
    except (InvalidOperation, ValueError, TypeError):
        return default

def _default_min_credits(level: str) -> Decimal:
    defaults = {
        "ASC": Decimal("60"),
        "BSC": Decimal("120"),
        "MSC": Decimal("36"),
        "PHD": Decimal("84"),
    }
    return defaults.get((level or "").upper(), Decimal("120"))

def _to_int(value: Any, default: int = 0) -> int:
    try:
        if value is None or value == "":
            return default
        return int(value)
    except (TypeError, ValueError):
        return default

def _month_delta(start_date, end_date) -> int:
    if not start_date or not end_date:
        return 0
    months = (end_date.year - start_date.year) * 12 + (
        end_date.month - start_date.month
    )
    if end_date.day < start_date.day:
        months -= 1
    return months

def is_course_satisfied(code: str) -> bool:
    normalized = _normalize_course_code(code)
    if not normalized:
        return False
    if normalized in waived_codes:
        return True
    if normalized in completed_course_codes:
        return True
    for equivalent in equivalencies.get(normalized, []):
        if equivalent in waived_codes or equivalent in completed_course_codes:
            return True
    return False

