    if ServiceIntegration.objects.filter(
        school=school, is_active=True, service_name__icontains="scim"
    ).exists():
        return "green"
    return "amber"

def _saml_oidc_hint(school) -> str:
    try:
        from apps.integrations_marketplace.models import Integration

        if (
            Integration.objects.filter(school=school, enabled=True)
            .filter(Q(provider__icontains="saml") | Q(provider__icontains="oidc"))
            .exists()
        ):
            return "green"
    except Exception:
        pass
    return "amber"

def mask_token_preview(token: str | None) -> str:
    if not token:
        return ""
    t = str(token).strip()
    if len(t) <= 8:
        return "(set)" if t else ""
    return t[:6] + "…"

def summarize_api_result(obj: Any, *, max_len: int = 4000) -> str:
    try:
        s = json.dumps(obj, indent=2, default=str)
    except TypeError:
        s = str(obj)
    if len(s) > max_len:
        return s[: max_len - 20] + "\n…(truncated)"
    return s

