def is_supported_algorithm(algorithm: str) -> bool:
    """Return True iff a verifier is registered for the slug."""
    return get_verifier(algorithm) is not None

def verify(
    algorithm: str, params: dict, stored_hash: str, password: str
) -> bool:
    """Verify ``password`` against ``stored_hash`` under ``algorithm``.

    Returns ``False`` on unknown algorithm, malformed hash, or any
    exception inside the verifier — the auth backend treats a False
    return as "no match", never as "error". This is intentional: a
    corrupted legacy row must never raise through the auth path.
    """
    verifier = get_verifier(algorithm)
    if verifier is None:
        return False
    try:
        result = verifier.verify(password, stored_hash, params or {})
    except (ValueError, TypeError, ImportError):
        # Defensive: a corrupted row shouldn't crash login. ImportError
        # bubbles up only if bcrypt is missing — the operator should see
        # that via the structured docket, not via a 500.
        return False
    return bool(result.matched)

def _checkpw(password: str, stored_hash: str) -> bool:
    """Verify ``password`` against a bcrypt-format ``stored_hash``."""
    pw_bytes = password.encode("utf-8")
    hash_bytes = stored_hash.encode("utf-8")
    try:
        import bcrypt  # type: ignore[import-not-found]
    except ImportError:
        pass
    else:
        try:
            return bool(bcrypt.checkpw(pw_bytes, hash_bytes))
        except (ValueError, TypeError):
            return False

    try:
        from passlib.hash import bcrypt as passlib_bcrypt  # type: ignore[import-not-found]
    except ImportError as exc:
        raise ImportError(
            "Bcrypt verification requires either the 'bcrypt' or 'passlib' "
            "package. Install one: pip install bcrypt"
        ) from exc

    try:
        return bool(passlib_bcrypt.verify(password, stored_hash))
    except (ValueError, TypeError):
        return False

def verify_bcrypt(password: str, stored_hash: str) -> VerifierResult:
    """Verify a bcrypt-style hash. Returns a non-sensitive VerifierResult."""
    if not password or not stored_hash:
        return VerifierResult(matched=False, reason="empty_input")
    if not stored_hash.startswith(("$2a$", "$2b$", "$2y$")):
        return VerifierResult(matched=False, reason="not_bcrypt_format")
    matched = _checkpw(password, stored_hash)
