def _parse_date(value: str):
    """Accept YYYY-MM-DD, DD/MM/YYYY, MM/DD/YYYY. Return date or None."""
    value = _normalize(value)
    if not value:
        return None
    for fmt in ("%Y-%m-%d", "%d/%m/%Y", "%m/%d/%Y", "%Y/%m/%d"):
        try:
            return datetime.strptime(value, fmt).date()
        except ValueError:
            continue
    return None

