def _anonymize_ip(ip: str) -> str:
    """Anonymize IP for GDPR (e.g. after 90 days): keep only first two octets for IPv4."""
    if not ip or ":" in ip:
        return ip[: min(len(ip), 10)] + "..." if ip else ""
    parts = ip.split(".")
    if len(parts) >= 2:
        return f"{parts[0]}.{parts[1]}.0.0"
    return ip

