def text_contains_disallowed_sql_fragment(text: str) -> bool:
    t = (text or "").lower()
    return any(m in t for m in _UNSAFE_MARKERS)

def match_governed_intent(text: str) -> GovernedIntentMatch:
    raw = (text or "").strip()
    if not raw:
        return GovernedIntentMatch(supported=False, reason="empty")

    if text_contains_disallowed_sql_fragment(raw):
        return GovernedIntentMatch(supported=False, reason="disallowed_fragment")

    norm = " ".join(raw.lower().split())
    for intent_id, label, pattern, definition, insight in _INTENT_SPEC:
        if pattern.search(norm):
            spec = dict(definition)
            filt = dict(spec.get("filters") or {})
            if intent_id == "attendance_gaps":
                filt["date__gte"] = _rolling_date_gte_iso(30)
                spec["filters"] = filt
            return GovernedIntentMatch(
                supported=True,
                intent_id=intent_id,
                label=label,
                governed_definition=spec,
                insight=dict(insight),
            )

    return GovernedIntentMatch(supported=False, reason="not_supported")

def insight_for_intent(intent_id: str) -> dict[str, Any] | None:
    for iid, _lab, _pat, _defn, insight in _INTENT_SPEC:
        if iid == intent_id:
            return dict(insight)
    return None

def rebuild_definition_for_intent(intent_id: str) -> dict[str, Any] | None:
    """Server-side reconstruction for execute path (do not trust client definition bodies)."""
    for iid, _lab, _pat, definition, _ins in _INTENT_SPEC:
        if iid == intent_id:
            spec = dict(definition)
            if intent_id == "attendance_gaps":
                filt = dict(spec.get("filters") or {})
                filt["date__gte"] = _rolling_date_gte_iso(30)
                spec["filters"] = filt
            return spec
    return None

def _get_model(meta: dict):
    path = meta["model"]
    app_label, model_name = path.split(".", 1)
    return apps.get_model(app_label, model_name)

def _user_can_access(user, meta: dict) -> bool:
    if getattr(user, "is_superuser", False):
        return True
    perms: tuple[str, ...] = meta["permissions"]
    return any(user.has_feature_permission(p) for p in perms)

def _validate_fields(meta: dict, fields: list[str]) -> list[str]:
    allowed = set(meta["fields"])
    out = []
    for f in fields:
        if f not in allowed:
            raise GovernedQueryError(f"field not allowed: {f}")
        out.append(f)
    return out or list(meta["fields"])[:8]

def _apply_filters(qs, meta: dict, filters: dict[str, Any]):
    allowed = meta["filters"]
    for key, val in (filters or {}).items():
        if key not in allowed:
            raise GovernedQueryError(f"filter not allowed: {key}")
        qs = qs.filter(**{key: val})
    return qs

def _agg_expr(fn: str, field: str):
    fn_l = fn.lower()
    if fn_l == "count":
        return Count(field)
    if fn_l == "sum":
        return Sum(field)
    if fn_l == "avg":
        return Avg(field)
    if fn_l == "min":
        return Min(field)
    if fn_l == "max":
        return Max(field)
    raise GovernedQueryError(f"aggregation not allowed: {fn}")

