                "EXPLAIN SELECT id FROM siteconfig_aiembeddingstore "
                "WHERE scope='student' "
                "ORDER BY embedding_vec <=> %s::vector "
                "LIMIT 10",
                [probe],
            )
            plan_lines = [r[0] for r in cur.fetchall()]
