def _sanitize_definition(raw: dict | None) -> dict:
    out: dict = {}
    if not isinstance(raw, dict):
        return out
    for k in _ALLOWED_DEFINITION_KEYS:
        if k not in raw:
            continue
        if k == "limit":
            try:
                out[k] = min(max(int(raw[k]), 1), 5000)
            except (TypeError, ValueError):
                out[k] = 200
        else:
            out[k] = raw[k]
    return out

