def _merge_origins(static: Iterable[str], dynamic: Iterable[str]) -> list[str]:
    seen: set[str] = set()
    merged: list[str] = []
    for origin in list(static) + list(dynamic):
        norm = _normalize_origin(origin)
        if norm and norm not in seen:
            seen.add(norm)
            merged.append(norm)
    return merged

class TenantCorsAllowlistMiddleware:
    """
