def _json_body(request: HttpRequest) -> dict[str, Any] | None:
    try:
        payload = json.loads(request.body.decode("utf-8") or "{}")
    except (UnicodeDecodeError, json.JSONDecodeError):
        return None
    return payload if isinstance(payload, dict) else None

def _scim_error(detail: str, *, status: int = 400, scim_type: str | None = None):
    payload = {
        "schemas": ["urn:ietf:params:scim:api:messages:2.0:Error"],
        "detail": detail,
        "status": str(status),
    }
    if scim_type:
        payload["scimType"] = scim_type
    return JsonResponse(payload, status=status)

def _resolve_school(request: HttpRequest):
    school = getattr(request, "school", None)
    if school:
        return school
    school_slug = (request.GET.get("school_slug") or "").strip() or (
        request.headers.get("X-School-Slug") or ""
    ).strip()
    if not school_slug:
        return None
    return School.objects.filter(slug=school_slug, is_active=True).first()

def _resolve_scim_integration(school):
    return resolve_service_integration(
        school,
        service_type=ServiceIntegration.ServiceType.OAUTH,
        service_name="scim",
        name_hints=["scim"],
        allow_legacy_backfill=True,
    )

def _extract_bearer(request: HttpRequest) -> str:
    auth = (request.headers.get("Authorization") or "").strip()
    if not auth.lower().startswith("bearer "):
        return ""
    return auth[7:].strip()

def _scim_replay_check(request: HttpRequest) -> JsonResponse | None:
    """
    Optional replay protection (public_endpoint_audit §6 / GAP.4).
    If X-SCIM-Timestamp (Unix seconds) is present, reject if outside SCIM_REPLAY_WINDOW_SECONDS.
    If header absent, allow (backward compatible).
    """
    raw = (request.headers.get("X-SCIM-Timestamp") or "").strip()
    if not raw:
        return None
    try:
        ts = int(raw)
    except ValueError:
        return _scim_error("Invalid X-SCIM-Timestamp", status=401)
    now = int(time.time())
    if abs(now - ts) > SCIM_REPLAY_WINDOW_SECONDS:
        logger.warning(
            "SCIM request rejected: timestamp outside replay window",
            extra={"path": request.path},
        )
        return _scim_error("Request timestamp outside allowed window", status=401)
    return None

def _scim_signature_check(request: HttpRequest, *, shared_secret: str) -> JsonResponse | None:
    """
    Optional request-body integrity (PATH Phase II.1 / public_endpoint_audit Section 6).
    If X-SCIM-Signature is present, it must be ``sha256=<hex>`` where *hex* is the
    HMAC-SHA256 of ``request.body`` using the same shared secret as the bearer token.
    If absent, allow (backward compatible).
    """
    raw = (request.headers.get("X-SCIM-Signature") or "").strip()
    if not raw:
        return None
    prefix = "sha256="
    if len(raw) < len(prefix) or raw[: len(prefix)].lower() != prefix:
        return _scim_error(
            "Invalid X-SCIM-Signature format (expected sha256=<hex>)", status=401
        )
    hex_part = raw[len(prefix) :].strip()
    if len(hex_part) != 64:
        return _scim_error("Invalid X-SCIM-Signature digest length", status=401)
    try:
        expected_sig = bytes.fromhex(hex_part)
    except ValueError:
        return _scim_error("Invalid X-SCIM-Signature digest", status=401)
    computed = hmac.new(
        shared_secret.encode("utf-8"),
        request.body,
        hashlib.sha256,
    ).digest()
    if not hmac.compare_digest(computed, e

def _authorize_scim_request(request: HttpRequest):
    replay_err = _scim_replay_check(request)
    if replay_err:
        return None, None, replay_err
    school = _resolve_school(request)
    if not school:
        return None, None, _scim_error("School context required", status=400)
    integration = _resolve_scim_integration(school)
    if not integration:
        return (
            None,
            None,
            _scim_error("SCIM integration not configured for school", status=503),
        )
    expected = (
        str((integration.config or {}).get("bearer_token") or "").strip()
        or str(integration.client_secret or "").strip()
    )
    provided = _extract_bearer(request)
    if not expected or not provided or not secrets.compare_digest(expected, provided):
        logger.warning(
            "Rejected SCIM request with invalid bearer token",
            extra={"school_slug": getattr(school, "slug", ""), "path": request.path},
        )
        return None, None, _scim_error("Unauthorized", status=403)
    nonce_err = _scim_nonce_replay_check(request, namespace=expected)
    if nonce_err:
        return None, None, nonce_err
    sig_err = _scim_signature_check

def _log_scim_request(request: HttpRequest, *, resource: str) -> None:
    """Audit log for every authenticated SCIM request (no PII). public_endpoint_audit Step 8."""
    logger.info(
        "SCIM request",
        extra={
            "path": request.path,
            "method": request.method,
            "resource": resource,
            "authenticated": True,
        },
    )

def _resolve_scim_mutation_body(
    request: HttpRequest, *, school, resource: str
) -> tuple[dict[str, Any] | None, JsonResponse | None]:
    content_type = (
        (
            (request.content_type or request.META.get("CONTENT_TYPE") or "").split(
                ";", 1
            )[0]
        )
        .strip()
        .lower()
    )
    if content_type not in SCIM_MUTATION_CONTENT_TYPES:
        _log_scim_rejection(
            request,
            school=school,
            resource=resource,
            reason="unsupported_content_type",
            status=415,
        )
        return None, _scim_error(
            "Content-Type must be application/scim+json or application/json", status=415
        )
    body = _json_body(request)
    if body is None:
        _log_scim_rejection(
            request,
            school=school,
            resource=resource,
            reason="invalid_json",
            status=400,
        )
        return None, _scim_error(
            "Invalid JSON body", status=400, scim_type="invalidSyntax"
        )
    return body, None

def _list_response(
    resources: list[dict[str, Any]],
    *,
    start_index: int = 1,
    total_results: int | None = None,
):
    payload = {
        "schemas": [SCIM_LIST_SCHEMA],
        "totalResults": int(
            total_results if total_results is not None else len(resources)
        ),
        "startIndex": int(start_index),
        "itemsPerPage": len(resources),
        "Resources": resources,
    }
    return JsonResponse(payload, status=200)

def _parse_positive_int(raw: Any, *, default: int, minimum: int, maximum: int) -> int:
    try:
        value = int(raw)
    except (TypeError, ValueError):
        value = default
    return max(minimum, min(maximum, value))

