    """
    from apps.people.models import StudentProfile

    created_ids = (run.rollback_snapshot or {}).get("created_ids") or []
    if not created_ids:
        return {
            "success": True,
            "message": "No created_ids in snapshot; nothing to revert.",
            "reverted_count": 0,
