    school = getattr(run, "school", None)
    if not school:
        return {"success": False, "message": "Run has no school.", "reverted_count": 0}
    qs = StudentProfile.objects.filter(pk__in=created_ids, school=school)
    count = qs.count()
    qs.delete()
    return {
