def snapshot(school: Any, *, day: _date | None = None) -> dict[str, int]:
    """Return ``{dimension: quantity}`` for the given UTC day."""
    if school is None:
        return {code: 0 for code in USAGE_DIMENSION_CODES}
    target_day = day or _today()
    try:
        from apps.billing.models import UsageMeter

        rows = UsageMeter.objects.filter(
            school=school,
            period_start=target_day,
            period_end=target_day,
            metric_code__in=USAGE_DIMENSION_CODES,
        ).values_list("metric_code", "quantity")
    except (ImportError, RuntimeError):
        return {code: 0 for code in USAGE_DIMENSION_CODES}
    out = {code: 0 for code in USAGE_DIMENSION_CODES}
    for code, qty in rows:
        out[code] = int(qty or 0)
    return out

def active_stripe_price_for_plan(
    plan_code: str, *, billing_cycle: str | None = None, currency: str | None = None
) -> StripePlanPrice | None:
    code = str(plan_code or "").strip()
    if not code:
        return None
    qs = StripePlanPrice.objects.filter(plan_code=code, is_active=True)
    if billing_cycle:
        qs = qs.filter(billing_cycle=str(billing_cycle).strip().upper())
    if currency:
        c = str(currency).strip().upper()
        if len(c) == 3:
            qs = qs.filter(currency=c)
    return qs.order_by("-updated_at").first()

def _request_header(request: HttpRequest, header_name: str) -> str:
    return (
        request.headers.get(header_name)
        or request.META.get(f"HTTP_{header_name.upper().replace('-', '_')}")
        or ""
    )

def _parse_json_body(raw_body: bytes) -> dict:
    if not raw_body:
        return {}
    try:
        payload = json.loads(raw_body.decode("utf-8"))
    except (TypeError, ValueError, json.JSONDecodeError):
        return {}
    return payload if isinstance(payload, dict) else {}

def _hexdigest(secret: str, raw_body: bytes, algorithm: str) -> str:
    hash_impl = getattr(hashlib, algorithm, None)
    if hash_impl is None:
        raise ValueError(f"Unsupported signature algorithm: {algorithm}")
    return hmac.new(secret.encode(), raw_body, hash_impl).hexdigest()

def _to_decimal_minor_units(value) -> Decimal | None:
    if value in (None, ""):
        return None
    return (Decimal(str(value)) / Decimal("100")).quantize(Decimal("0.01"))

def _to_datetime_from_unix(value) -> datetime | None:
    if value in (None, ""):
        return None
    try:
        return datetime.fromtimestamp(int(value), tz=dt_timezone.utc)
    except (TypeError, ValueError, OSError):
        return None

def _parse_response_json(raw_text: str) -> dict:
    try:
        payload = json.loads(raw_text or "{}")
