def get_document_hash(document_text: str) -> str:
    """SHA-256 of document text at sign time."""
    return hashlib.sha256((document_text or "").encode("utf-8")).hexdigest()

def get_pending_consents_for_user(user, school):
    """Consent requests that user has not yet signed (or that are outdated)."""
    if not school:
        return []
    signed_ids = set(
        ConsentRecord.objects.filter(
            user=user, school=school, withdrawn_at__isnull=True
        )
        .values_list("consent_request_id", flat=True)
        .filter(consent_request_id__isnull=False)
    )
    qs = ConsentRequest.objects.filter(school=school, is_active=True).order_by(
        "due_date", "-created_at"
    )
    return [r for r in qs if r.id not in signed_ids]

def get_completed_consents_for_user(user, school):
    """Consent records (audit) for Permission Hub 'Completed' list."""
    if not school:
        return []
    return list(
        ConsentRecord.objects.filter(user=user, school=school)
        .select_related("consent_request")
        .order_by("-signed_at")[:50]
    )

def create_consent_record(
    user, school, title: str, document_text: str, request=None, consent_request=None
):
    """Record signature with SHA-256 hash; IP from request."""
    doc_hash = get_document_hash(document_text)
    ip = None
    if request:
        try:
            from ipware import get_client_ip

            ip, _ = get_client_ip(request)
        except ImportError:
            ip = request.META.get("REMOTE_ADDR")
    return ConsentRecord.objects.create(
        school=school,
        user=user,
        consent_request=consent_request,
        title=title,
        document_hash=doc_hash,
        ip_address=ip,
        document_version_at_sign=consent_request.document_version_id
        if consent_request
        else None,
    )

def cross_border_export_blocked(
    school: Any,
    *,
    destination_region: str | None = None,
) -> tuple[bool, str]:
    """
    Return (blocked, message). Soft by default; strict when DATA_RESIDENCY_ENFORCE=1.
    """
    if school is None:
        return False, ""

    school_region = (
        str(getattr(school, "data_region", None) or "").strip().lower()
    )
    if not school_region:
        return False, ""

    dest = (destination_region or "").strip().lower()
    if not dest:
        return False, ""

    if school_region == dest:
        return False, ""

    enforce = os.environ.get("DATA_RESIDENCY_ENFORCE", "").strip() in (
        "1",
        "true",
        "yes",
    ) or getattr(settings, "DATA_RESIDENCY_ENFORCE", False)

    if not enforce:
        return False, ""

    return (
        True,
        f"Export blocked: school data_region={school_region!r} does not match "
        f"active region={dest!r}. Adjust residency or use in-region operator session.",
    )

def data_quality_checks(school_id: Any = None, *, school: Any = None) -> list[dict[str, Any]]:
    """Run each registered check against the given tenant scope.

    Accepts either ``school_id`` (legacy positional) or ``school=`` (preferred).
    Returns a list of dicts (ready to JSON-serialize / render).
    """
    if school is None and school_id is not None:
        from apps.schools.models import School

        school = School.objects.filter(pk=school_id).first()
    if school is None:
        return []
    issues: list[DataQualityIssue] = []
    for check in DATA_QUALITY_CHECKS:
        try:
            issue = check(school)
        except Exception:  # noqa: BLE001 - one broken check must not break the report
            continue
        if issue is not None:
            issues.append(issue)
    return [i.to_dict() for i in issues]

def summarize(issues: Iterable[dict[str, Any]]) -> dict[str, int]:
    """Roll-up: counts per severity, used by the meter component."""
    out = {SEVERITY_BLOCKER: 0, SEVERITY_WARNING: 0, SEVERITY_INFO: 0, "total": 0}
    for it in issues:
        sev = it.get("severity") or SEVERITY_INFO
        out[sev] = out.get(sev, 0) + 1
        out["total"] += 1
    return out

def _resolve_object_id(request, kwargs: dict, object_id_kwarg: str) -> str:
    value = kwargs.get(object_id_kwarg)
    if value is None:
        value = request.GET.get(object_id_kwarg) or request.POST.get(object_id_kwarg)
    return str(value) if value not in (None, "") else ""

def _client_ip(request) -> Optional[str]:
    xff = request.META.get("HTTP_X_FORWARDED_FOR")
    if xff:
        return xff.split(",")[0].strip()
    return request.META.get("REMOTE_ADDR") or None

