    action = str(details.get("gdpr_action") or "").strip()
    if action:
        return action

    text = (description or "").upper()
    if "ART. 20" in text or "PORTABILITY" in text:
        return "art20_portability"
    if "ART. 17" in text or "ERASURE" in text:
        return "art17_erasure"
    return ""

